insert into public.projects (id, slug, title, subtitle, category, client, industry, summary, description, quote, author_name, author_role, image_url, accent, year, tags, status, featured, sort_order, created_at, updated_at) values (1, 'fsi-iqueño-admin', 'FSI IQUEÑO ADMIN', 'Panel administrativo para centralizar la gestión y operación interna de FSI SAC.', 'Software Empresarial / Panel Administrativo', 'FABRICACIONES Y SERVICIOS EL IQUEÑO SAC', 'Servicios Empresariales', 'Panel administrativo desarrollado para FSI SAC, diseñado para centralizar la gestión de información, usuarios y procesos internos de la empresa.', $kt$FSI IQUEÑO ADMIN es una plataforma web administrativa desarrollada para FSI SAC con el objetivo de centralizar y facilitar la gestión de sus procesos internos.
El sistema proporciona un entorno privado para administrar la información de la empresa de manera organizada, permitiendo reducir procesos manuales y disponer de la información desde una única plataforma.
La interfaz fue diseñada bajo un enfoque moderno, responsive y orientado a la usabilidad, permitiendo trabajar desde computadoras, tablets y dispositivos móviles.$kt$, 'KARVATECH nos construyó un CRM a medida que centralizó nuestras ventas. Hoy nuestros asesores gastan la mitad del tiempo en reportes.', 'Karla Albites', 'Administradora Comercial · Metalisteria', '/static/uploads/proy_20260922_172525_6a0949.png', '#16a34a', '2025', ARRAY['Software Empresarial', 'Panel Administrativo', 'Gestión', 'Dashboard', 'CRUD', 'Usuarios', 'Reportes']::text[], 'publicado', false, 1, '2026-09-22 00:04:59.763655+00:00'::timestamptz, '2026-09-24 07:13:26.199906+00:00'::timestamptz) on conflict (id) do update set slug = excluded.slug, title = excluded.title, subtitle = excluded.subtitle, category = excluded.category, client = excluded.client, industry = excluded.industry, summary = excluded.summary, description = excluded.description, quote = excluded.quote, author_name = excluded.author_name, author_role = excluded.author_role, image_url = excluded.image_url, accent = excluded.accent, year = excluded.year, tags = excluded.tags, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, created_at = excluded.created_at, updated_at = excluded.updated_at;
insert into public.projects (id, slug, title, subtitle, category, client, industry, summary, description, quote, author_name, author_role, image_url, accent, year, tags, status, featured, sort_order, created_at, updated_at) values (2, 'netland-panel-administrativo-inmobiliario', 'NETLAND — Panel Administrativo Inmobiliario', 'Plataforma integral para gestionar proyectos inmobiliarios, ventas, clientes, cobranzas, lotes y operaciones comerciales desde un solo sistema.', 'ERP / CRM / Gestión Inmobiliaria', 'CORPORACION INMOBILIARIA NETLAND', 'Inmobiliaria / Bienes Raíces', 'Sistema integral de gestión inmobiliaria que centraliza proyectos, lotes, clientes, ventas, cobranzas, contratos, comisiones y operaciones comerciales en una plataforma web.', $kt$NETLAND Panel Administrativo es una plataforma web desarrollada para centralizar la gestión operativa y comercial de una empresa inmobiliaria.
El sistema permite administrar desde un único entorno los proyectos inmobiliarios, lotes, clientes, propietarios, ventas, contratos, cobranzas, asesores, comisiones y diferentes procesos internos de la organización.
Uno de sus principales componentes es el CRM inmobiliario, que permite registrar y realizar seguimiento de prospectos, asignar asesores, gestionar estados comerciales, programar visitas y controlar el proceso de conversión desde el primer contacto hasta la venta.
La plataforma también incorpora herramientas especializadas para la gestión de proyectos y lotes, incluyendo estados de disponibilidad, precios, recargos, descuentos y visualización de planos interactivos.$kt$, 'El ERP implementado unificó inventario y finanzas. Pasamos de hojas de Excel a decisiones en tiempo real. El soporte es excelente.', 'Nancy', 'Administradora · Distribuidora', '/static/uploads/proy_20260922_171545_65bf25.png', '#13ae25', '2026', ARRAY['CRM', 'ERP', 'Inmobiliaria', 'Ventas', 'Cobranzas', 'Lotes', 'Comisiones']::text[], 'publicado', true, 1, '2026-09-22 00:04:59.984436+00:00'::timestamptz, '2026-09-24 07:08:57.893035+00:00'::timestamptz) on conflict (id) do update set slug = excluded.slug, title = excluded.title, subtitle = excluded.subtitle, category = excluded.category, client = excluded.client, industry = excluded.industry, summary = excluded.summary, description = excluded.description, quote = excluded.quote, author_name = excluded.author_name, author_role = excluded.author_role, image_url = excluded.image_url, accent = excluded.accent, year = excluded.year, tags = excluded.tags, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, created_at = excluded.created_at, updated_at = excluded.updated_at;
insert into public.projects (id, slug, title, subtitle, category, client, industry, summary, description, quote, author_name, author_role, image_url, accent, year, tags, status, featured, sort_order, created_at, updated_at) values (3, 'netland-web', 'NETLAND-WEB', 'Plataforma web inmobiliaria interactiva para descubrir proyectos, explorar lotes y contactar con asesores comerciales.', 'Desarrollo Web / Plataforma Inmobiliaria', 'CORPORACION INMOBILIARIA NETLAND', 'Inmobiliaria / Bienes Raíces', 'Plataforma web inmobiliaria que permite explorar proyectos, consultar la disponibilidad de lotes en tiempo real y contactar directamente con asesores comerciales.', $kt$NETLAND-WEB es la plataforma pública desarrollada para Netland Corporación Inmobiliaria, diseñada para ofrecer a potenciales compradores una experiencia digital moderna para conocer y explorar sus proyectos inmobiliarios.
La plataforma permite presentar los proyectos disponibles, visualizar información comercial, consultar lotes y conocer su disponibilidad de manera interactiva.
Uno de sus principales componentes es el plano interactivo, que permite visualizar los lotes de cada proyecto y consultar su estado, facilitando al usuario la exploración de las propiedades disponibles.$kt$, 'La atención pasó de perder tiempo en papeles a vender mas lotes y brindando mas confiabilidad.', 'Dr. Richard', 'Gerente General', '/static/uploads/proy_20260922_171623_026d27.png', '#0ea5e9', '2025', ARRAY['Inmobiliaria', 'Desarrollo Web', 'Responsive', 'SEO', 'Lotes', 'CRM', 'WhatsApp']::text[], 'publicado', true, 3, '2026-09-22 00:05:00.201471+00:00'::timestamptz, '2026-09-24 07:17:16.680659+00:00'::timestamptz) on conflict (id) do update set slug = excluded.slug, title = excluded.title, subtitle = excluded.subtitle, category = excluded.category, client = excluded.client, industry = excluded.industry, summary = excluded.summary, description = excluded.description, quote = excluded.quote, author_name = excluded.author_name, author_role = excluded.author_role, image_url = excluded.image_url, accent = excluded.accent, year = excluded.year, tags = excluded.tags, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, created_at = excluded.created_at, updated_at = excluded.updated_at;
insert into public.projects (id, slug, title, subtitle, category, client, industry, summary, description, quote, author_name, author_role, image_url, accent, year, tags, status, featured, sort_order, created_at, updated_at) values (4, 'sigei-sistema-de-gestión-educativa-integral', 'SIGEI — Sistema de Gestión Educativa Integral', 'ERP educativo basado en microservicios para la gestión de instituciones educativas públicas del Perú.', 'ERP / Sistemas Educativos / Microservicios', 'Proyecto académico — Desarrollo de Software', 'Educación / Sector Público', 'SIGEI es un ERP educativo diseñado para centralizar y optimizar la gestión académica y administrativa de instituciones educativas públicas del Perú mediante una arquitectura de microservicios preparada para el escalamiento horizontal.', $kt$SIGEI (Sistema de Gestión Educativa Integral) es una plataforma ERP orientada a la gestión de instituciones educativas públicas del Perú.
El sistema fue desarrollado utilizando una arquitectura basada en microservicios, permitiendo dividir las funcionalidades del sistema en servicios independientes y facilitando su mantenimiento, evolución y escalamiento.
La solución contempla la gestión de procesos académicos y administrativos, incluyendo módulos especializados para la gestión de matrículas y períodos académicos.
Uno de los principales objetivos técnicos del proyecto fue implementar una arquitectura preparada para el escalamiento horizontal, permitiendo incrementar la capacidad del sistema mediante la incorporación de nuevas instancias de los servicios cuando aumenta la demanda.$kt$, 'Los padres ven el avance de sus hijos y la administración ahorra horas por día.', 'Lucía Mendoza', 'Directora Académica', '/static/uploads/proy_20260922_171740_37d0ca.png', '#7c3aed', '2025', ARRAY['ERP', 'Educación', 'Microservicios', 'Java', 'Spring Boot', 'React', 'PostgreSQL', 'Keycloak']::text[], 'entregado', false, 4, '2026-09-22 00:05:00.417517+00:00'::timestamptz, '2026-09-24 06:57:35.139428+00:00'::timestamptz) on conflict (id) do update set slug = excluded.slug, title = excluded.title, subtitle = excluded.subtitle, category = excluded.category, client = excluded.client, industry = excluded.industry, summary = excluded.summary, description = excluded.description, quote = excluded.quote, author_name = excluded.author_name, author_role = excluded.author_role, image_url = excluded.image_url, accent = excluded.accent, year = excluded.year, tags = excluded.tags, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, created_at = excluded.created_at, updated_at = excluded.updated_at;
insert into public.projects (id, slug, title, subtitle, category, client, industry, summary, description, quote, author_name, author_role, image_url, accent, year, tags, status, featured, sort_order, created_at, updated_at) values (5, 'luka-bot-crm-inteligente-multicanal', 'LUKA-BOT — CRM Inteligente Multicanal', 'Plataforma CRM multitenant para gestionar conversaciones, clientes y canales de atención desde un solo lugar.', 'CRM / Inteligencia Artificial / Automatización', 'Proyecto propio — KARVATECH', 'Tecnología / Servicios Empresariales', 'LUKA-BOT es una plataforma CRM multitenant y multicanal que permite a diferentes empresas gestionar clientes y conversaciones automatizadas mediante un único sistema.', $kt$LUKA-BOT es una plataforma de gestión empresarial desarrollada para centralizar la atención al cliente y automatizar conversaciones mediante un chatbot inteligente.
Su arquitectura multitenant permite que diferentes empresas utilicen la misma plataforma manteniendo separados sus usuarios, configuraciones, clientes, conversaciones y datos.
El sistema incorpora un enfoque multicanal, permitiendo centralizar las conversaciones provenientes de diferentes canales de comunicación en una sola plataforma.
Entre sus principales funcionalidades se encuentran la gestión de clientes, conversaciones, usuarios, empresas, configuración del chatbot, automatización de respuestas y seguimiento de interacciones.
El proyecto fue diseñado con una arquitectura escalable, orientada a convertirse en una solución SaaS, permitiendo incorporar nuevas empresas y funcionalidades sin necesidad de crear una instalación independiente para cada cliente.$kt$, '"Una solución que permite centralizar la atención al cliente y automatizar gran parte de las conversaciones desde una sola plataforma."', 'Cliente / Responsable del proyecto', 'Responsable del proyecto', '/static/uploads/proy_20260922_171810_9b54c6.png', '#059669', '2025', ARRAY['CRM', 'Chatbot', 'Inteligencia Artificial', 'Multitenant', 'Multicanal', 'Automatización', 'Atención al Cliente', 'SaaS']::text[], 'entregado', true, 5, '2026-09-22 00:05:00.634688+00:00'::timestamptz, '2026-09-24 06:42:15.145449+00:00'::timestamptz) on conflict (id) do update set slug = excluded.slug, title = excluded.title, subtitle = excluded.subtitle, category = excluded.category, client = excluded.client, industry = excluded.industry, summary = excluded.summary, description = excluded.description, quote = excluded.quote, author_name = excluded.author_name, author_role = excluded.author_role, image_url = excluded.image_url, accent = excluded.accent, year = excluded.year, tags = excluded.tags, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, created_at = excluded.created_at, updated_at = excluded.updated_at;
insert into public.projects (id, slug, title, subtitle, category, client, industry, summary, description, quote, author_name, author_role, image_url, accent, year, tags, status, featured, sort_order, created_at, updated_at) values (6, 'web-fsi-sac', 'WEB-FSI SAC', 'Sitio web corporativo moderno y responsive para fortalecer la presencia digital de FSI SAC.', 'Desarrollo Web / Sitio Corporativo', 'FSI SAC', 'Servicios Empresariales', 'Sitio web corporativo desarrollado para FSI SAC, con diseño moderno, responsive y orientado a presentar sus servicios, información empresarial y canales de contacto.', $kt$PLATAFORMA WEB-FSI SAC es un sitio web corporativo desarrollado para fortalecer la presencia digital de la empresa y ofrecer a sus clientes una experiencia moderna, clara y adaptable a diferentes dispositivos.
La plataforma presenta de manera organizada la información de la empresa, sus principales servicios y canales de contacto, facilitando que los visitantes conozcan la propuesta de la organización y puedan comunicarse con ella.
El proyecto fue desarrollado con un enfoque en diseño responsive, experiencia de usuario, rendimiento y accesibilidad, permitiendo una correcta visualización en computadoras, tablets y dispositivos móviles.$kt$, 'El resultado es una presencia web profesional que permite a FSI SAC mostrar sus servicios y facilitar el contacto con potenciales clientes desde cualquier dispositivo.', 'Karla Albites', 'Administradora Comercial', '/static/uploads/proy_20260922_171909_8a4b7e.png', '#f59e0b', '2025', ARRAY['Desarrollo Web', 'Web Corporativa', 'Responsive', 'React', 'TypeScript', 'UI/UX', 'SEO', 'Diseño Web']::text[], 'publicado', false, 6, '2026-09-22 00:05:01.172254+00:00'::timestamptz, '2026-09-24 07:03:26.699724+00:00'::timestamptz) on conflict (id) do update set slug = excluded.slug, title = excluded.title, subtitle = excluded.subtitle, category = excluded.category, client = excluded.client, industry = excluded.industry, summary = excluded.summary, description = excluded.description, quote = excluded.quote, author_name = excluded.author_name, author_role = excluded.author_role, image_url = excluded.image_url, accent = excluded.accent, year = excluded.year, tags = excluded.tags, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, created_at = excluded.created_at, updated_at = excluded.updated_at;

-- --------------------------------------------------------------------------
-- Secuencias
-- --------------------------------------------------------------------------
--
-- Los ids se copiaron tal cual desde Neon y no empiezan en 1, asi que las
-- secuERIAL quedan atrasadas. Sin esto, el siguiente insert del formulario
-- de contacto falla con duplicate key.

select setval(pg_get_serial_sequence('public.messages', 'id'), greatest(coalesce((select max(id) from public.messages), 1), 1), true);  -- -> 8
select setval(pg_get_serial_sequence('public.projects', 'id'), greatest(coalesce((select max(id) from public.projects), 1), 1), true);  -- -> 6

-- Verificacion: deben salir 2 y 6.
select (select count(*) from public.messages) as mensajes,
       (select count(*) from public.projects) as proyectos;
